/**
 * AST を JSON 化可能なプレーンオブジェクトに変換する。
 * `meta.fn` にはプラグイン関数の実体が入るため、JSON.stringify が黙って捨てて
 * しまわないよう replacer で目印に置き換える。
 */
export function toPlainAst (ast) {
  return JSON.parse(JSON.stringify(ast, (key, value) => (typeof value === 'function' ? '[fn]' : value)))
}

/** なでしこのコードを構文解析してプレーンな AST を返す */
export function parseToPlainAst (code) {
  return toPlainAst(new NakoCompiler().parse(code, CORPUS_FILENAME))
}
